pub struct Renderer {
    presenter: Option<crate::presentation::Presenter>,
    inner: Mutex<RendererInner>,
    raw_storage_resident:
        Arc<Mutex<nexium_common::fast_hash::FastSet<crate::compute::ComputeRawStorageKey>>>,
    device: ash::Device,
    submit_timeline: vk::Semaphore,
    submit_state: Arc<SubmitState>,
}

pub(crate) struct SubmitState {
    generation: std::sync::atomic::AtomicU64,
    last_idle_generation: std::sync::atomic::AtomicU64,
    pub(crate) sequence: std::sync::Mutex<()>,
    pub(crate) presentation_sequence: std::sync::Mutex<()>,
}

impl Drop for Renderer {
    fn drop(&mut self) {
        self.presenter.take();
    }
}

impl SubmitState {
    fn new() -> Self {
        Self {
            generation: std::sync::atomic::AtomicU64::new(0),
            last_idle_generation: std::sync::atomic::AtomicU64::new(u64::MAX),
            sequence: std::sync::Mutex::new(()),
            presentation_sequence: std::sync::Mutex::new(()),
        }
    }

    fn note_queue_drained(&self) {
        self.last_idle_generation.store(
            self.generation.load(std::sync::atomic::Ordering::Acquire),
            std::sync::atomic::Ordering::Release,
        );
    }
}

#[derive(Clone, Debug, PartialEq)]
pub struct GraphicsClearOp {
    pub color: Option<GraphicsColorClear>,
    pub depth_stencil: Option<GraphicsDepthStencilClear>,
}

#[derive(Clone, Debug, PartialEq)]
pub struct GraphicsColorClear {
    pub key: RtKey,
    pub format: vk::Format,
    pub rgba: [f32; 4],
    pub rect: Option<[i32; 4]>,
}

#[derive(Clone, Debug, PartialEq)]
pub struct GraphicsDepthStencilClear {
    pub key: RtKey,
    pub format: vk::Format,
    pub aspects: vk::ImageAspectFlags,
    pub clear_aspects: vk::ImageAspectFlags,
    pub depth: f32,
    pub stencil: u32,
}

impl GraphicsClearOp {
    pub fn is_valid(&self) -> bool {
        let color_valid = self.color.as_ref().is_some_and(|clear| {
            clear.key.width != 0
                && clear.key.height != 0
                && !clear.key.is_3d
                && clear.key.render_layer_count() == 1
        });
        let depth_valid = self.depth_stencil.as_ref().is_some_and(|clear| {
            clear.key.width != 0
                && clear.key.height != 0
                && !clear.key.is_3d
                && clear.key.render_layer_count() == 1
                && !clear.aspects.is_empty()
                && !clear.clear_aspects.is_empty()
                && clear.aspects.contains(clear.clear_aspects)
        });
        let combined_valid = match (&self.color, &self.depth_stencil) {
            (Some(color), Some(depth)) => {
                color.key.width == depth.key.width
                    && color.key.height == depth.key.height
                    && color.key != depth.key
                    && !same_physical_backing(color.key, depth.key)
            }
            _ => true,
        };
        (self.color.is_none() || color_valid)
            && (self.depth_stencil.is_none() || depth_valid)
            && combined_valid
            && (self.color.is_some() || self.depth_stencil.is_some())
    }
}

#[derive(Clone, Copy, Debug, Default)]
pub struct RtAliasTelemetry {
    pub binds: u64,
    pub binds_after_raw_snapshot: u64,
}

static RT_ALIAS_TELEMETRY_BINDS: std::sync::atomic::AtomicU64 =
    std::sync::atomic::AtomicU64::new(0);
static RT_ALIAS_TELEMETRY_BINDS_AFTER_RAW_SNAPSHOT: std::sync::atomic::AtomicU64 =
    std::sync::atomic::AtomicU64::new(0);

#[inline]
fn rt_alias_telemetry_enabled() -> bool {
    static ENABLED: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ENABLED.get_or_init(|| std::env::var_os("NEXIUM_KICKOFF_PROFILE").is_some())
}

#[inline]
fn record_rt_alias_bind(after_raw_snapshot: bool) {
    if !rt_alias_telemetry_enabled() {
        return;
    }
    RT_ALIAS_TELEMETRY_BINDS.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    if after_raw_snapshot {
        RT_ALIAS_TELEMETRY_BINDS_AFTER_RAW_SNAPSHOT
            .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    }
}

pub fn take_rt_alias_telemetry() -> RtAliasTelemetry {
    if !rt_alias_telemetry_enabled() {
        return RtAliasTelemetry::default();
    }
    RtAliasTelemetry {
        binds: RT_ALIAS_TELEMETRY_BINDS.swap(0, std::sync::atomic::Ordering::Relaxed),
        binds_after_raw_snapshot: RT_ALIAS_TELEMETRY_BINDS_AFTER_RAW_SNAPSHOT
            .swap(0, std::sync::atomic::Ordering::Relaxed),
    }
}

fn idle_skip_disabled() -> bool {
    static DISABLED: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *DISABLED.get_or_init(|| std::env::var_os("NEXIUM_NO_IDLE_SKIP").is_some())
}

pub const GRAPHICS_RING_CAPACITY_BYTES: u64 = 256 * 1024 * 1024;
pub const GRAPHICS_RING_SAFE_BATCH_BYTES: u64 = GRAPHICS_RING_CAPACITY_BYTES / 2;
const GRAPHICS_FRAME_SLOT_COUNT: usize = 2;
const MAX_STORAGE_BUFFER_OFFSET_ALIGNMENT: u64 = 256;
const DEFAULT_CLEAR_SLOT_COUNT: usize = 4;
const MAX_CLEAR_SLOT_COUNT: usize = 64;

fn graphics_frame_slot_count() -> usize {
    static COUNT: std::sync::OnceLock<usize> = std::sync::OnceLock::new();
    *COUNT.get_or_init(|| {
        let requested = std::env::var("NEXIUM_RENDER_FRAME_SLOTS")
            .ok()
            .and_then(|value| value.parse::<usize>().ok())
            .filter(|count| (2..=8).contains(count))
            .unwrap_or(GRAPHICS_FRAME_SLOT_COUNT);
        const SAFE_RING_SLOT_COUNT: usize = GRAPHICS_FRAME_SLOT_COUNT;
        if requested != SAFE_RING_SLOT_COUNT {
            log::warn!(
                "Vulkan graphics frame slots requested {}; forcing {} until the shared graphics ring has per-slot ranges",
                requested,
                SAFE_RING_SLOT_COUNT
            );
        }
        SAFE_RING_SLOT_COUNT
    })
}

fn clear_slot_count() -> usize {
    static COUNT: std::sync::OnceLock<usize> = std::sync::OnceLock::new();
    *COUNT.get_or_init(|| {
        let count = std::env::var("NEXIUM_CLEAR_SLOT_COUNT")
            .ok()
            .and_then(|value| value.parse::<usize>().ok())
            .filter(|count| (1..=MAX_CLEAR_SLOT_COUNT).contains(count))
            .unwrap_or(DEFAULT_CLEAR_SLOT_COUNT);
        if count != DEFAULT_CLEAR_SLOT_COUNT {
            log::info!(
                "Vulkan clear-slot pool configured for {} slots (default {})",
                count,
                DEFAULT_CLEAR_SLOT_COUNT
            );
        }
        count
    })
}

fn frame_slot_submission_complete(
    device: &ash::Device,
    submit_timeline: vk::Semaphore,
    generation: u64,
) -> bool {
    if generation == 0 {
        return false;
    }
    if submit_timeline == vk::Semaphore::null() {
        return false;
    }
    unsafe {
        device
            .get_semaphore_counter_value(submit_timeline)
            .is_ok_and(|completed| completed >= generation)
    }
}

#[derive(Clone, Debug)]
pub struct SharedGuestSnapshot {
    data: Arc<Vec<u8>>,
    len: usize,
    trusted_identity: Option<u64>,
}

impl SharedGuestSnapshot {
    pub fn new(data: Arc<Vec<u8>>, len: usize) -> Option<Self> {
        (len <= data.len()).then_some(Self {
            data,
            len,
            trusted_identity: None,
        })
    }

    pub fn new_trusted(data: Arc<Vec<u8>>, len: usize, identity: u64) -> Option<Self> {
        (identity != 0 && len <= data.len()).then_some(Self {
            data,
            len,
            trusted_identity: Some(identity),
        })
    }

    pub fn from_vec(data: Vec<u8>) -> Self {
        let len = data.len();
        Self {
            data: Arc::new(data),
            len,
            trusted_identity: None,
        }
    }

    pub fn as_slice(&self) -> &[u8] {
        &self.data[..self.len]
    }

    pub fn trusted_identity(&self) -> Option<u64> {
        self.trusted_identity
    }

    fn make_mut(&mut self) -> &mut Vec<u8> {
        if self.len != self.data.len() {
            self.data = Arc::new(self.as_slice().to_vec());
        }
        self.trusted_identity = None;
        Arc::make_mut(&mut self.data)
    }
}

impl std::ops::Deref for SharedGuestSnapshot {
    type Target = [u8];

    fn deref(&self) -> &Self::Target {
        self.as_slice()
    }
}

impl AsRef<[u8]> for SharedGuestSnapshot {
    fn as_ref(&self) -> &[u8] {
        self.as_slice()
    }
}

fn ring_request_upper_bound(size: u64, alignment: u64) -> u64 {
    align_up(size, alignment).saturating_add(alignment.saturating_sub(1))
}

type SharedSsboKey = (u32, usize, u64);
const AURORA_VERTEX_BUFFER_SIZE: usize = 3 * 1024 * 1024;
const AURORA_STORAGE_BUFFER_SIZE: usize = 8 * 1024 * 1024;

fn shared_aurora_ssbo_key(snapshot: &crate::draw::StorageBufferSnapshot) -> Option<SharedSsboKey> {
    let aurora_arena = matches!(
        snapshot.logical_size,
        AURORA_VERTEX_BUFFER_SIZE | AURORA_STORAGE_BUFFER_SIZE
    );
    let complete_payload =
        snapshot.data_offset == 0 && snapshot.data.len() == snapshot.logical_size;
    (aurora_arena && complete_payload).then_some((
        snapshot.binding,
        snapshot.logical_size,
        snapshot.guest_addr,
    ))
}

#[derive(Clone, Debug)]
struct SharedSsboPatch {
    start: usize,
    source_offset: usize,
    len: usize,
    source: std::sync::Arc<Vec<u8>>,
}

impl SharedSsboPatch {
    fn end(&self) -> usize {
        self.start + self.len
    }

    fn bytes(&self) -> &[u8] {
        &self.source[self.source_offset..self.source_offset + self.len]
    }
}

#[derive(Clone, Debug)]
struct SharedSsboSource {
    data_offset: usize,
    data: std::sync::Arc<Vec<u8>>,
}

impl SharedSsboSource {
    fn matches(&self, snapshot: &crate::draw::StorageBufferSnapshot) -> bool {
        self.data_offset == snapshot.data_offset
            && std::sync::Arc::ptr_eq(&self.data, &snapshot.data)
    }
}

