fn texture_content_hash(bytes: &[u8]) -> u64 {
    xxhash_rust::xxh3::xxh3_64(bytes)
}

fn memoized_texture_snapshot_hash(
    hashes: &mut HashMap<(u64, usize), u64>,
    range: (u64, usize),
    snapshot: &[u8],
) -> u64 {
    debug_assert_eq!(range.1, snapshot.len());
    *hashes
        .entry(range)
        .or_insert_with(|| texture_content_hash(snapshot))
}

#[derive(Clone, Copy, Default)]
struct TextureHashProfile {
    snapshots: u64,
    snapshot_bytes: u64,
    trusted: u64,
    repeated: u64,
    repeated_bytes: u64,
    hashes: u64,
    hash_bytes: u64,
    hash_repeated_bytes: u64,
    hash_time: std::time::Duration,
    memo_hits: u64,
    memo_bytes: u64,
}

impl TextureHashProfile {
    fn observe(&mut self, snapshot: &SharedGuestSnapshot, previous: Option<u64>) -> bool {
        self.snapshots += 1;
        self.snapshot_bytes += snapshot.len() as u64;
        let identity = snapshot.trusted_identity();
        self.trusted += u64::from(identity.is_some());
        let repeated = identity.is_some() && identity == previous;
        if repeated {
            self.repeated += 1;
            self.repeated_bytes += snapshot.len() as u64;
        }
        repeated
    }

    fn add(&mut self, other: Self) {
        self.snapshots += other.snapshots;
        self.snapshot_bytes += other.snapshot_bytes;
        self.trusted += other.trusted;
        self.repeated += other.repeated;
        self.repeated_bytes += other.repeated_bytes;
        self.hashes += other.hashes;
        self.hash_bytes += other.hash_bytes;
        self.hash_repeated_bytes += other.hash_repeated_bytes;
        self.hash_time += other.hash_time;
        self.memo_hits += other.memo_hits;
        self.memo_bytes += other.memo_bytes;
    }
}

fn profiled_texture_snapshot_hash(
    hashes: &mut HashMap<(u64, usize), u64>,
    range: (u64, usize),
    snapshot: &[u8],
    repeated_identity: bool,
    profile: &mut TextureHashProfile,
) -> u64 {
    use std::collections::hash_map::Entry;

    match hashes.entry(range) {
        Entry::Occupied(entry) => {
            profile.memo_hits += 1;
            profile.memo_bytes += snapshot.len() as u64;
            *entry.get()
        }
        Entry::Vacant(entry) => {
            let started = std::time::Instant::now();
            let hash = texture_content_hash(snapshot);
            profile.hash_time += started.elapsed();
            profile.hashes += 1;
            profile.hash_bytes += snapshot.len() as u64;
            if repeated_identity {
                profile.hash_repeated_bytes += snapshot.len() as u64;
            }
            entry.insert(hash);
            hash
        }
    }
}

fn cached_cpu_texture_hash(
    cached: Option<(u64, usize, u64)>,
    snapshot: &SharedGuestSnapshot,
) -> Option<u64> {
    let (identity, len, hash) = cached?;
    (snapshot.trusted_identity() == Some(identity) && snapshot.len() == len).then_some(hash)
}

fn trusted_texture_snapshot_matches(
    cached_identity: Option<u64>,
    snapshot: Option<&SharedGuestSnapshot>,
) -> bool {
    snapshot
        .and_then(SharedGuestSnapshot::trusted_identity)
        .is_some_and(|identity| Some(identity) == cached_identity)
}

fn resolve_texture_generation<F>(
    generation: &mut Option<u64>,
    query: &mut Option<F>,
    required: bool,
) -> Option<u64>
where
    F: FnOnce() -> u64,
{
    if generation.is_none() && required {
        *generation = query.take().map(|query| query());
    }
    *generation
}

fn sampled_texture_needs_upload(
    force_refresh: bool,
    cached_generation_and_hash: Option<(u64, u64)>,
    current_generation: u64,
    texture_hash: u64,
    content_hash_authoritative: bool,
    trusted_snapshot_match: bool,
) -> bool {
    if force_refresh {
        return true;
    }
    if trusted_snapshot_match {
        return false;
    }
    let Some((cached_generation, cached_hash)) = cached_generation_and_hash else {
        return true;
    };
    if content_hash_authoritative {
        cached_hash != texture_hash
    } else {
        cached_generation != current_generation || cached_hash != texture_hash
    }
}

