    #[test]
    fn pipeline_prewarm_is_default_on_with_explicit_false_rollback() {
        use std::ffi::OsStr;

        assert!(pipeline_prewarm_value_enabled(None));
        assert!(pipeline_prewarm_value_enabled(Some(OsStr::new("1"))));
        assert!(pipeline_prewarm_value_enabled(Some(OsStr::new("true"))));
        for disabled in ["0", "false", "OFF", " no "] {
            assert!(!pipeline_prewarm_value_enabled(Some(OsStr::new(disabled))));
        }
    }

    #[test]
    fn texture_generations_are_untrusted_until_explicitly_enabled() {
        use std::ffi::OsStr;

        assert!(!tex_gen_gating_value_enabled(None));
        for disabled in ["", "0", "false", "OFF", " no "] {
            assert!(!tex_gen_gating_value_enabled(Some(OsStr::new(disabled))));
        }
        for enabled in ["1", "true", "on", "yes"] {
            assert!(tex_gen_gating_value_enabled(Some(OsStr::new(enabled))));
        }
    }

    #[test]
    fn texture_snapshot_hash_memo_reuses_exact_ranges_and_restarts_after_clear() {
        let first = [1, 2, 3, 4];
        let changed = [9, 2, 3, 4];
        let longer = [1, 2, 3, 4, 5];
        let first_hash = texture_content_hash(&first);
        let changed_hash = texture_content_hash(&changed);
        let mut hashes = HashMap::new();

        assert_eq!(
            memoized_texture_snapshot_hash(&mut hashes, (0x4000, first.len()), &first),
            first_hash
        );
        assert_eq!(
            memoized_texture_snapshot_hash(&mut hashes, (0x4000, changed.len()), &changed),
            first_hash
        );
        assert_eq!(
            memoized_texture_snapshot_hash(&mut hashes, (0x5000, changed.len()), &changed),
            changed_hash
        );
        assert_eq!(
            memoized_texture_snapshot_hash(&mut hashes, (0x4000, longer.len()), &longer),
            texture_content_hash(&longer)
        );
        assert_eq!(hashes.len(), 3);

        hashes.clear();
        assert_eq!(
            memoized_texture_snapshot_hash(&mut hashes, (0x4000, changed.len()), &changed),
            changed_hash
        );
    }

    #[test]
    fn trusted_snapshot_identity_matches_only_exact_immutable_content() {
        let data = std::sync::Arc::new(vec![1, 2, 3, 4]);
        let trusted = SharedGuestSnapshot::new_trusted(data.clone(), 4, 17).unwrap();
        let ordinary = SharedGuestSnapshot::new(data, 4).unwrap();

        assert!(trusted_texture_snapshot_matches(Some(17), Some(&trusted)));
        assert!(!trusted_texture_snapshot_matches(Some(19), Some(&trusted)));
        assert!(!trusted_texture_snapshot_matches(Some(17), Some(&ordinary)));
        assert!(!trusted_texture_snapshot_matches(None, Some(&trusted)));

        let mut mutated = trusted.clone();
        mutated.make_mut()[0] = 9;
        assert_eq!(mutated.trusted_identity(), None);
        assert!(!trusted_texture_snapshot_matches(Some(17), Some(&mutated)));
        assert_eq!(trusted.as_slice(), &[1, 2, 3, 4]);
    }

    #[test]
    fn cached_cpu_hash_rejects_replaced_resized_and_mutated_snapshots() {
        let bytes = std::sync::Arc::new(vec![1, 2, 3, 4]);
        let snapshot = SharedGuestSnapshot::new_trusted(bytes.clone(), 4, 17).unwrap();
        let hash = texture_content_hash(snapshot.as_slice());
        let cached = Some((17, 4, hash));
        assert_eq!(super::cached_cpu_texture_hash(cached, &snapshot), Some(hash));
        let replaced = SharedGuestSnapshot::new_trusted(bytes.clone(), 4, 18).unwrap();
        let resized = SharedGuestSnapshot::new_trusted(bytes.clone(), 3, 17).unwrap();
        let untrusted = SharedGuestSnapshot::new(bytes, 4).unwrap();
        for different in [&replaced, &resized, &untrusted] {
            assert_eq!(super::cached_cpu_texture_hash(cached, different), None);
        }
        let mut mutated = snapshot.clone();
        mutated.make_mut()[0] = 9;
        assert_eq!(super::cached_cpu_texture_hash(cached, &mutated), None);
        assert_eq!(super::cached_cpu_texture_hash(None, &snapshot), None);
    }

    #[test]
    fn texture_hash_profile_separates_actual_work_memo_hits_and_trusted_repeats() {
        let snapshot =
            SharedGuestSnapshot::new_trusted(std::sync::Arc::new(vec![1, 2, 3, 4]), 4, 17).unwrap();
        let mut profile = super::TextureHashProfile::default();
        let mut memo = HashMap::new();
        let range = (0x1000, snapshot.len());
        assert!(!profile.observe(&snapshot, None));
        assert_eq!(
            super::profiled_texture_snapshot_hash(
                &mut memo,
                range,
                snapshot.as_slice(),
                false,
                &mut profile,
            ),
            texture_content_hash(snapshot.as_slice())
        );
        assert!(profile.observe(&snapshot, Some(17)));
        super::profiled_texture_snapshot_hash(
            &mut memo,
            range,
            snapshot.as_slice(),
            true,
            &mut profile,
        );
        assert_eq!((profile.hashes, profile.hash_bytes), (1, 4));
        assert_eq!((profile.memo_hits, profile.memo_bytes), (1, 4));
        assert_eq!(profile.hash_repeated_bytes, 0);
        memo.clear();
        super::profiled_texture_snapshot_hash(
            &mut memo,
            range,
            snapshot.as_slice(),
            true,
            &mut profile,
        );
        assert_eq!((profile.hashes, profile.hash_bytes), (2, 8));
        assert_eq!(profile.hash_repeated_bytes, 4);
        assert!(!profile.observe(&SharedGuestSnapshot::from_vec(vec![1, 2, 3, 4]), None));
        assert_eq!((profile.snapshots, profile.snapshot_bytes), (3, 12));
        assert_eq!(
            (profile.trusted, profile.repeated, profile.repeated_bytes),
            (2, 1, 4)
        );
    }

    #[test]
    fn texture_generation_query_is_skipped_until_required() {
        let calls = std::cell::Cell::new(0);
        let mut generation = None;
        let mut query = Some(|| {
            calls.set(calls.get() + 1);
            41
        });

        assert_eq!(
            resolve_texture_generation(&mut generation, &mut query, false),
            None
        );
        assert_eq!(calls.get(), 0);
        assert_eq!(
            resolve_texture_generation(&mut generation, &mut query, true),
            Some(41)
        );
        assert_eq!(calls.get(), 1);
    }

    #[test]
    fn texture_generation_query_runs_at_most_once() {
        let calls = std::cell::Cell::new(0);
        let mut generation = None;
        let mut query = Some(|| {
            calls.set(calls.get() + 1);
            73
        });

        assert_eq!(
            resolve_texture_generation(&mut generation, &mut query, true),
            Some(73)
        );
        assert_eq!(
            resolve_texture_generation(&mut generation, &mut query, true),
            Some(73)
        );
        assert_eq!(calls.get(), 1);
    }

    #[test]
    fn ordinary_volume_uploads_changed_trusted_content_at_the_same_generation() {
        let cached_bytes = [1, 2, 3, 4];
        let changed = SharedGuestSnapshot::new_trusted(
            std::sync::Arc::new(vec![9, 2, 3, 4]),
            cached_bytes.len(),
            18,
        )
        .unwrap();
        let cached_identity = Some(17);
        let trusted_match = trusted_texture_snapshot_matches(cached_identity, Some(&changed));
        let generation = 41;

        assert!(!trusted_match);
        assert!(sampled_texture_needs_upload(
            false,
            Some((generation, texture_content_hash(&cached_bytes))),
            generation,
            texture_content_hash(changed.as_slice()),
            true,
            trusted_match,
        ));
    }

    #[test]
    fn ordinary_volume_reuses_an_unchanged_exact_trusted_identity() {
        let bytes = std::sync::Arc::new(vec![1, 2, 3, 4]);
        let unchanged = SharedGuestSnapshot::new_trusted(bytes, 4, 17).unwrap();
        let trusted_match = trusted_texture_snapshot_matches(Some(17), Some(&unchanged));

        assert!(trusted_match);
        assert!(!sampled_texture_needs_upload(
            false,
            Some((40, texture_content_hash(unchanged.as_slice()))),
            41,
            0,
            false,
            trusted_match,
        ));
    }

    #[test]
    fn mip_overlays_validate_gpu_changes_and_restore_cpu_cache_after_disappearing() {
        use crate::texture_mips::{texture_rt_mip_hash, TextureRtMip};

        let snapshot =
            SharedGuestSnapshot::new_trusted(std::sync::Arc::new(vec![1, 2, 3, 4]), 4, 17).unwrap();
        let raw_hash = texture_content_hash(snapshot.as_slice());
        let cpu_hash = texture_rt_mip_hash(raw_hash, &[]);
        let mut cached = super::CachedTexture {
            image: vk::Image::null(),
            view: vk::ImageView::null(),
            memory: vk::DeviceMemory::null(),
            layout: vk::ImageLayout::SHADER_READ_ONLY_OPTIMAL,
            hash: cpu_hash,
            gen: 41,
            trusted_source_identity: Some(17),
            gpu_mip_overlay: false,
            raw_cpu_hash: Some(raw_hash),
            gpu_subresources: Vec::new(),
            cpu_snapshot_hash: Some((17, snapshot.len(), raw_hash)),
            invalidated: false,
            allocation_size: 4096,
        };
        let mip = TextureRtMip {
            level: 0,
            layer: 0,
            width: 512,
            height: 512,
            key: RtKey::new(642, 512, 512, 0x5a4970000),
            image: vk::Image::from_raw(101),
            layout: vk::ImageLayout::COLOR_ATTACHMENT_OPTIMAL,
            format: vk::Format::R16_SFLOAT,
            stamp: 7,
        };
        let decide = |texture: &super::CachedTexture, mips: &[TextureRtMip]| {
            let validate = super::texture_mip_overlay_needs_validation(Some(texture), mips);
            let trusted = !validate
                && trusted_texture_snapshot_matches(
                    texture.trusted_source_identity,
                    Some(&snapshot),
                );
            (
                validate,
                sampled_texture_needs_upload(
                    false,
                    Some((texture.gen, texture.hash)),
                    41,
                    texture_rt_mip_hash(
                        super::cached_cpu_texture_hash(texture.cpu_snapshot_hash, &snapshot)
                            .expect("CPU hash remains reusable while GPU mip stamps change"),
                        mips,
                    ),
                    true,
                    trusted,
                ),
            )
        };
        assert_eq!(decide(&cached, &[]), (false, false));
        assert_eq!(decide(&cached, &[mip]), (true, true));
        cached.gpu_mip_overlay = true;
        cached.hash = texture_rt_mip_hash(raw_hash, &[mip]);
        assert_eq!(decide(&cached, &[mip]), (true, false));
        assert_eq!(
            decide(&cached, &[TextureRtMip { stamp: 8, ..mip }]),
            (true, true)
        );
        assert_eq!(decide(&cached, &[]), (true, true));
        cached.gpu_mip_overlay = false;
        cached.hash = cpu_hash;
        assert_eq!(decide(&cached, &[]), (false, false));
        assert_eq!(decide(&cached, &[mip]), (true, true));
    }

    #[test]
    fn gpu_mip_refresh_requires_unchanged_cpu_backing_and_preserved_coverage() {
        use crate::texture_mips::{texture_rt_mip_hash, TextureRtMip};

        let key = TexCacheKey {
            width: 512,
            height: 512,
            mip_levels: 8,
            view_mips: 8,
            ..group_memo_test_key(0x5a4970000)
        };
        let raw_hash = texture_content_hash(&[0; 64]);
        let mut cached = super::CachedTexture {
            image: vk::Image::from_raw(100),
            view: vk::ImageView::from_raw(101),
            memory: vk::DeviceMemory::from_raw(102),
            layout: vk::ImageLayout::SHADER_READ_ONLY_OPTIMAL,
            hash: texture_rt_mip_hash(raw_hash, &[]),
            gen: 1,
            trusted_source_identity: Some(17),
            gpu_mip_overlay: false,
            raw_cpu_hash: Some(raw_hash),
            gpu_subresources: Vec::new(),
            cpu_snapshot_hash: None,
            invalidated: false,
            allocation_size: 4096,
        };
        let base = TextureRtMip {
            level: 0,
            layer: 0,
            width: 512,
            height: 512,
            key: RtKey::new(642, 512, 512, 0x5a4970000),
            image: vk::Image::from_raw(201),
            layout: vk::ImageLayout::COLOR_ATTACHMENT_OPTIMAL,
            format: vk::Format::R16_SFLOAT,
            stamp: 7,
        };
        let lower = TextureRtMip {
            level: 1,
            width: 256,
            height: 256,
            key: RtKey::new(642, 256, 256, 0x5a49f0000),
            image: vk::Image::from_raw(202),
            ..base
        };
        let eligible = |texture: &super::CachedTexture, cpu_hash, mips: &[TextureRtMip]| {
            super::texture_rt_mips_can_refresh(texture, &key, cpu_hash, mips)
        };
        assert!(eligible(&cached, Some(raw_hash), &[base]));
        assert!(!eligible(&cached, None, &[base]));
        assert!(!eligible(&cached, Some(texture_content_hash(&[1; 64])), &[base]));
        cached.gpu_mip_overlay = true;
        cached.gpu_subresources = super::texture_rt_subresources(&[base]);
        cached.hash = texture_rt_mip_hash(raw_hash, &[base]);
        assert!(!sampled_texture_needs_upload(
            false,
            Some((cached.gen, cached.hash)),
            cached.gen,
            texture_rt_mip_hash(raw_hash, &[base]),
            true,
            false,
        ));
        let changed = TextureRtMip { stamp: 8, ..base };
        assert!(sampled_texture_needs_upload(
            false,
            Some((cached.gen, cached.hash)),
            cached.gen,
            texture_rt_mip_hash(raw_hash, &[changed]),
            true,
            false,
        ));
        assert!(eligible(&cached, Some(raw_hash), &[changed]));
        assert!(eligible(&cached, Some(raw_hash), &[changed, lower]));
        cached.gpu_subresources = super::texture_rt_subresources(&[changed, lower]);
        assert!(!eligible(&cached, Some(raw_hash), &[changed]));
        assert!(!eligible(&cached, Some(raw_hash), &[lower]));
        assert!(!eligible(&cached, Some(raw_hash), &[]));
        cached.gpu_mip_overlay = false;
        cached.gpu_subresources.clear();
        cached.hash = texture_rt_mip_hash(raw_hash, &[]);
        assert!(eligible(&cached, Some(raw_hash), &[base]));
        for invalid in [
            TextureRtMip {
                image: cached.image,
                ..base
            },
            TextureRtMip {
                image: vk::Image::null(),
                ..base
            },
            TextureRtMip { width: 256, ..base },
            TextureRtMip { level: 32, ..base },
            TextureRtMip {
                layout: vk::ImageLayout::UNDEFINED,
                ..base
            },
        ] {
            assert!(!eligible(&cached, Some(raw_hash), &[invalid]));
        }
        let array_key = TexCacheKey { arrayed: true, layers: 2, ..key };
        let second_layer = TextureRtMip { layer: 1, ..base };
        cached.gpu_subresources = super::texture_rt_subresources(&[base, second_layer]);
        assert!(super::texture_rt_mips_can_refresh(
            &cached, &array_key, Some(raw_hash), &[base, second_layer]));
        assert!(!super::texture_rt_mips_can_refresh(
            &cached, &array_key, Some(raw_hash), &[base]));
        assert!(!super::texture_rt_mips_can_refresh(
            &cached, &array_key, Some(raw_hash), &[second_layer]));
        assert!(!super::texture_rt_mips_can_refresh(
            &cached, &key, Some(raw_hash), &[base, second_layer]));
        cached.gpu_subresources.clear();
        cached.layout = vk::ImageLayout::UNDEFINED;
        assert!(!eligible(&cached, Some(raw_hash), &[base]));
        cached.layout = vk::ImageLayout::SHADER_READ_ONLY_OPTIMAL;
        cached.raw_cpu_hash = None;
        assert!(!eligible(&cached, Some(raw_hash), &[base]));
    }

