    #[test]
    fn texture_range_index_matches_scan_through_insert_remove_and_clear() {
        use std::collections::HashSet;
        let mut index = super::TextureRangeIndex::default();
        let mut keys = HashSet::new();
        let mut random = 7u64;
        for i in 0..512 {
            random = random.wrapping_mul(6364136223846793005).wrapping_add(1);
            let address = match i % 7 {
                0 => u64::MAX - (random & 0xffff),
                1 => 0x8000,
                _ => random & 0xfffff,
            };
            let mut key = group_memo_test_key(address);
            key.guest_size = random.rotate_left(17) & 0xffff;
            key.cube = i % 3 == 0;
            key.cube_array = i % 5 == 0;
            index.insert(key);
            index.insert(key);
            keys.insert(key);
        }
        let check = |index: &super::TextureRangeIndex, keys: &HashSet<TexCacheKey>| {
            for (address, size) in [(0, 0), (0, u64::MAX), (u64::MAX, 1),
                (u64::MAX - 0x8000, 0x10000), (0x8000, 1), (0x9000, 0x8000),
                (0x100000, 0x100000)] {
                let actual: HashSet<_> = index.overlapping(address, size).into_iter().collect();
                let expected: HashSet<_> = keys.iter().copied()
                    .filter(|key| texture_key_overlaps_gpu_range(*key, address, size)).collect();
                assert!(actual == expected, "query {address:#x}+{size:#x}");
            }
            assert_eq!(index.sizes.values().sum::<usize>(), keys.len());
            assert!(index.cubes == keys.iter().copied().filter(|key| key.cube || key.cube_array).collect());
        };
        check(&index, &keys);
        let removed: Vec<_> = keys.iter().copied().filter(|key| key.guest_size > 0x8000).collect();
        for key in removed {
            index.remove(key);
            index.remove(key);
            keys.remove(&key);
        }
        check(&index, &keys);
        index.clear();
        keys.clear();
        check(&index, &keys);
    }

    #[test]
    fn group_texture_descriptor_decode_memo_is_scoped_and_negative_exact() {
        let mut raw_tic = vec![0u8; 32];
        raw_tic[0..4].copy_from_slice(&0x1cu32.to_le_bytes());
        raw_tic[4..8].copy_from_slice(&1u32.to_le_bytes());
        let reads = std::cell::Cell::new(0usize);
        let read_tic = |addr: u64, len: usize| {
            assert_eq!(addr, 0x1000);
            assert_eq!(len, 32);
            reads.set(reads.get() + 1);
            Some(raw_tic.clone())
        };
        let mut memo = GroupTexturePrepMemo::default();
        let mut profile = RecordTextureMemoProfile::default();
        assert!(memoized_group_tic(&mut memo, 0x1000, &read_tic, &mut profile, true).is_some());
        assert!(memoized_group_tic(&mut memo, 0x1000, &read_tic, &mut profile, true).is_some());
        assert_eq!(reads.get(), 1);
        assert_eq!(profile.tic_requests, 2);
        assert_eq!(profile.tic_misses, 1);

        let missing_reads = std::cell::Cell::new(0usize);
        let read_missing = |_: u64, _: usize| -> Option<Vec<u8>> {
            missing_reads.set(missing_reads.get() + 1);
            None
        };
        let mut missing_memo = GroupTexturePrepMemo::default();
        assert!(memoized_group_tic(
            &mut missing_memo,
            0x2000,
            &read_missing,
            &mut profile,
            false,
        )
        .is_none());
        assert!(memoized_group_tic(
            &mut missing_memo,
            0x2000,
            &read_missing,
            &mut profile,
            false,
        )
        .is_none());
        assert_eq!(missing_reads.get(), 1);

        let mut next_group = GroupTexturePrepMemo::default();
        assert!(
            memoized_group_tic(&mut next_group, 0x1000, &read_tic, &mut profile, false,).is_some()
        );
        assert_eq!(reads.get(), 2);
    }

