    #[test]
    fn group_texture_binding_memo_requires_exact_safe_binding_and_evicts_uploads() {
        let route = GroupTextureRouteKey {
            tic_addr: 0x4000,
            numeric_type: 0,
            image_kind: crate::texture_manifest::GraphicsTextureImageKind::D2,
            arrayed_2d: false,
        };
        let key = group_memo_test_key(0x8000);
        let binding = HotGenericTextureBinding {
            key,
            generation: 7,
            trusted_source_identity: Some(17),
            image: vk::Image::from_raw(11),
            view: vk::ImageView::from_raw(12),
            layout: vk::ImageLayout::SHADER_READ_ONLY_OPTIMAL,
        };
        let mut bindings = HashMap::from([(route, binding)]);
        assert_eq!(
            group_texture_binding_lookup(&bindings, route, key).map(|hit| hit.view),
            Some(binding.view)
        );
        assert!(
            group_texture_binding_lookup(&bindings, route, TexCacheKey { width: 65, ..key })
                .is_none()
        );
        bindings.get_mut(&route).unwrap().layout = vk::ImageLayout::GENERAL;
        assert!(group_texture_binding_lookup(&bindings, route, key).is_none());
        bindings.get_mut(&route).unwrap().layout = vk::ImageLayout::SHADER_READ_ONLY_OPTIMAL;
        let other_route = GroupTextureRouteKey {
            tic_addr: 0x5000,
            ..route
        };
        assert!(group_texture_binding_lookup(&bindings, other_route, key).is_none());
        bindings.get_mut(&route).unwrap().trusted_source_identity = None;
        assert!(group_texture_binding_lookup(&bindings, route, key).is_none());
        bindings.get_mut(&route).unwrap().trusted_source_identity = Some(17);
        let other = HotGenericTextureBinding {
            key: group_memo_test_key(0x20000),
            ..binding
        };
        bindings.insert(other_route, other);
        assert!(texture_key_overlaps_gpu_range(key, 0x9000, 0x1000));
        assert!(!texture_key_overlaps_gpu_range(key, 0xc000, 0x1000));
        assert_eq!(
            group_texture_binding_evict_range(&mut bindings, 0x9000, 0x1000),
            1
        );
        assert_eq!(bindings.len(), 1);
        assert_eq!(
            bindings.get(&other_route).map(|entry| entry.view),
            Some(other.view)
        );
        let mut hot = [Some(binding), Some(other)];
        assert_eq!(
            hot_generic_texture_bindings_evict_range(&mut hot, 0xb000, 0x2000),
            1
        );
        assert!(hot[0].is_none());
        assert_eq!(hot[1].map(|entry| entry.view), Some(other.view));

        let tic = group_memo_test_tic(key.gpu_va);
        assert!(group_texture_binding_memo_eligible(
            key, tic, false, false, false
        ));
        assert!(!group_texture_binding_memo_eligible(
            key, tic, true, false, false
        ));
        assert!(!group_texture_binding_memo_eligible(
            key, tic, false, true, false
        ));
        assert!(!group_texture_binding_memo_eligible(
            key, tic, false, false, true
        ));
        assert!(!group_texture_binding_memo_eligible(
            TexCacheKey {
                volume: true,
                ..key
            },
            tic,
            false,
            false,
            false
        ));
        assert!(!group_texture_binding_memo_eligible(
            TexCacheKey { cube: true, ..key },
            tic,
            false,
            false,
            false
        ));
        assert!(!group_texture_binding_memo_eligible(
            TexCacheKey {
                cube_array: true,
                ..key
            },
            tic,
            false,
            false,
            false
        ));
        assert!(!group_texture_binding_memo_eligible(
            TexCacheKey {
                base_layer: 1,
                ..key
            },
            tic,
            false,
            false,
            false
        ));
        assert!(!group_texture_binding_memo_eligible(
            TexCacheKey { base_mip: 1, ..key },
            tic,
            false,
            false,
            false
        ));
        assert!(!group_texture_binding_memo_eligible(
            TexCacheKey {
                layers: 2,
                view_layers: 1,
                ..key
            },
            tic,
            false,
            false,
            false
        ));
        assert!(!group_texture_binding_memo_eligible(
            TexCacheKey {
                mip_levels: 2,
                view_mips: 1,
                ..key
            },
            tic,
            false,
            false,
            false
        ));
        let mut buffer_tic = tic;
        buffer_tic.texture_type = 6;
        assert!(!group_texture_binding_memo_eligible(
            key, buffer_tic, false, false, false
        ));
    }

