    #[test]
    fn cube_tic_uses_six_face_view_and_distinct_cache_identity() {
        use crate::texture::{ComponentType, SwizzleSource, TicEntry, TicFormat};
        use std::collections::HashSet;

        let tic = TicEntry {
            format: TicFormat::R8G8B8A8,
            component_types: [ComponentType::Unorm; 4],
            swizzle: [
                SwizzleSource::R,
                SwizzleSource::G,
                SwizzleSource::B,
                SwizzleSource::A,
            ],
            gpu_va: 0x110000,
            width: 64,
            height: 64,
            block_width_log2: 0,
            block_height_log2: 0,
            block_depth_log2: 0,
            tile_width_spacing: 0,
            pitch_bytes: 0,
            is_block_linear: false,
            texture_type: 3,
            depth: 1,
            base_layer: 4,
            normalized_coords: true,
            is_srgb: false,
            is_sparse: false,
            msaa_mode: 0,
            max_mip_level: 0,
            res_min_mip_level: 0,
            res_max_mip_level: 0,
        };
        assert!(tic_is_cube(&tic));
        assert_eq!(tic_layer_count(&tic), 6);
        assert_eq!(tic_storage_layer_count(&tic), 10);
        assert_eq!(tic_view_base_layer(&tic), 4);
        assert_eq!(tic_view_layer_count(&tic), 6);
        let pitch_size = tic.format.linear_size(tic.width, tic.height);
        assert_eq!(
            tic_read_size(&tic, pitch_size, tic_storage_layer_count(&tic)),
            pitch_size * 10
        );
        assert_eq!(tic.backing_gpu_va(), Some(0x100000));

        let plain = TexCacheKey {
            gpu_va: tic.backing_gpu_va().unwrap(),
            guest_size: tic_read_size(&tic, pitch_size, 10) as u64,
            width: tic.width,
            height: tic.height,
            layers: 10,
            base_layer: 4,
            view_layers: 6,
            mip_levels: 1,
            base_mip: 0,
            view_mips: 1,
            arrayed: false,
            cube: false,
            cube_array: false,
            volume: false,
            format: tic.format,
            component_types: tic.component_types,
            swizzle: tic.swizzle,
            is_srgb: tic.is_srgb,
            is_sparse: tic.is_sparse,
            msaa_mode: tic.msaa_mode,
            is_block_linear: tic.is_block_linear,
            block_width_log2: tic.block_width_log2,
            block_height_log2: tic.block_height_log2,
            block_depth_log2: tic.block_depth_log2,
            tile_width_spacing: tic.tile_width_spacing,
            pitch_bytes: tic.pitch_bytes,
            numeric_type: 0,
        };
        let cube = TexCacheKey {
            cube: true,
            ..plain
        };
        assert_eq!(HashSet::from([plain, cube]).len(), 2);

        let cube_array = route_texture_key_to_shader_image_kind(
            cube,
            &tic,
            crate::texture_manifest::GraphicsTextureImageKind::CubeArray,
        )
        .unwrap();
        assert!(!cube_array.cube);
        assert!(cube_array.cube_array);
        assert_eq!(cube_array.layers, 10);
        assert_eq!(cube_array.base_layer, 4);
        assert_eq!(cube_array.view_layers, 6);
        assert_eq!(HashSet::from([cube, cube_array]).len(), 2);
        assert_eq!(
            crate::texture_manifest::GraphicsTextureImageKind::CubeArray.spirv_kind(),
            nexium_spirv::GraphicsImageKind::CubeArray
        );
        assert_eq!(nexium_spirv::GFX_BINDING_FLOAT_CUBE_ARRAY, 13);

        let d2 = route_texture_key_to_shader_image_kind(
            cube,
            &tic,
            crate::texture_manifest::GraphicsTextureImageKind::D2,
        )
        .unwrap();
        assert!(!d2.arrayed && !d2.cube && !d2.cube_array && !d2.volume);
        assert_eq!((d2.layers, d2.view_layers), (10, 1));
        assert_eq!(
            texture_view_layer_range(10, 4, 1, false, false, false, false).unwrap(),
            (4, 1)
        );

        let float_components = TexCacheKey {
            component_types: [ComponentType::Float; 4],
            ..plain
        };
        let different_tiling = TexCacheKey {
            is_block_linear: true,
            block_height_log2: 4,
            ..plain
        };
        let different_pitch = TexCacheKey {
            pitch_bytes: 256,
            ..plain
        };
        let sparse = TexCacheKey {
            is_sparse: true,
            ..plain
        };
        let multisampled = TexCacheKey {
            msaa_mode: 2,
            ..plain
        };
        assert_eq!(
            HashSet::from([
                plain,
                float_components,
                different_tiling,
                different_pitch,
                sparse,
                multisampled,
            ])
            .len(),
            6
        );

        let arrayed = TexCacheKey {
            arrayed: true,
            ..plain
        };
        assert!(texture_key_has_special_view(arrayed));
        let mut two_d_tic = tic;
        two_d_tic.texture_type = 1;
        two_d_tic.base_layer = 0;
        two_d_tic.is_block_linear = true;
        assert!(!texture_key_blocks_2d_rt_alias(arrayed, &two_d_tic));
        assert!(texture_key_blocks_2d_rt_alias(cube, &two_d_tic));
        let mut array_tic = tic;
        array_tic.texture_type = 5;
        assert!(tic_requires_dedicated_sampled_view(&array_tic));
        assert!(texture_key_blocks_2d_rt_alias(arrayed, &array_tic));
        array_tic.depth = 2;
        assert!(texture_key_blocks_2d_rt_alias(arrayed, &array_tic));
    }

    #[test]
    fn render_target_alias_view_preserves_srgb_tic_formats() {
        use crate::texture::{ComponentType, SwizzleSource, TicEntry, TicFormat};

        let mut tic = TicEntry {
            format: TicFormat::A8B8G8R8,
            component_types: [ComponentType::Unorm; 4],
            swizzle: [
                SwizzleSource::R,
                SwizzleSource::G,
                SwizzleSource::B,
                SwizzleSource::A,
            ],
            gpu_va: 0x524c20000,
            width: 1600,
            height: 900,
            block_width_log2: 0,
            block_height_log2: 4,
            block_depth_log2: 0,
            tile_width_spacing: 0,
            pitch_bytes: 0,
            is_block_linear: true,
            texture_type: 1,
            depth: 1,
            base_layer: 0,
            normalized_coords: true,
            is_srgb: true,
            is_sparse: false,
            msaa_mode: 0,
            max_mip_level: 0,
            res_min_mip_level: 0,
            res_max_mip_level: 0,
        };
        let key = RtKey::new(1, tic.width, tic.height, tic.gpu_va);

        assert_eq!(
            rt_alias_view_format(key, tic, vk::Format::UNDEFINED),
            vk::Format::A8B8G8R8_SRGB_PACK32
        );
        tic.format = TicFormat::R8G8B8A8;
        assert_eq!(
            rt_alias_view_format(key, tic, vk::Format::UNDEFINED),
            vk::Format::R8G8B8A8_SRGB
        );
        tic.format = TicFormat::R8G8;
        assert_eq!(
            rt_alias_view_format(key, tic, vk::Format::UNDEFINED),
            vk::Format::R8G8_SRGB
        );
        tic.format = TicFormat::R8;
        assert_eq!(
            rt_alias_view_format(key, tic, vk::Format::UNDEFINED),
            vk::Format::R8_SRGB
        );
        tic.is_srgb = false;
        assert_eq!(
            rt_alias_view_format(key, tic, vk::Format::UNDEFINED),
            vk::Format::R8_UNORM
        );
        tic.is_srgb = true;
        tic.component_types = [ComponentType::Uint; 4];
        assert_eq!(
            rt_alias_view_format(key, tic, vk::Format::UNDEFINED),
            vk::Format::R8_UINT
        );
    }

    #[test]
    fn render_target_alias_view_allows_single_layer_array_and_rejects_unsupported_views() {
        use crate::texture::{ComponentType, SwizzleSource, TicEntry, TicFormat};

        let mut tic = TicEntry {
            format: TicFormat::B10G11R11,
            component_types: [ComponentType::Float; 4],
            swizzle: [
                SwizzleSource::R,
                SwizzleSource::G,
                SwizzleSource::B,
                SwizzleSource::One,
            ],
            gpu_va: 0x524c20000,
            width: 1600,
            height: 900,
            block_width_log2: 0,
            block_height_log2: 4,
            block_depth_log2: 0,
            tile_width_spacing: 0,
            pitch_bytes: 0,
            is_block_linear: true,
            texture_type: 5,
            depth: 1,
            base_layer: 0,
            normalized_coords: true,
            is_srgb: false,
            is_sparse: false,
            msaa_mode: 0,
            max_mip_level: 0,
            res_min_mip_level: 0,
            res_max_mip_level: 0,
        };

        assert!(tic_can_use_2d_rt_alias_view(&tic));
        tic.res_min_mip_level = 7;
        tic.res_max_mip_level = 15;
        assert_eq!(tic.view_base_mip(), 0);
        assert_eq!(tic.view_mip_levels(), 1);
        assert!(tic_can_use_2d_rt_alias_view(&tic));
        tic.res_min_mip_level = 0;
        tic.res_max_mip_level = 0;
        assert_eq!(
            rt_alias_sample_view_type(RtKey::new(1, 1600, 900, tic.gpu_va), Some(&tic), false,),
            vk::ImageViewType::TYPE_2D_ARRAY
        );
        tic.depth = 2;
        assert!(!tic_can_use_2d_rt_alias_view(&tic));
        tic.depth = 1;
        tic.texture_type = 1;
        assert!(tic_can_use_2d_rt_alias_view(&tic));
        tic.depth = 2;
        assert!(!tic_has_supported_rt_alias_layout(&tic));
        assert!(!tic_can_use_2d_rt_alias_view(&tic));
        tic.depth = 1;
        tic.base_layer = 1;
        assert!(!tic_can_use_2d_rt_alias_view(&tic));
        tic.base_layer = 0;

        tic.is_sparse = true;
        assert!(!tic_can_use_2d_rt_alias_view(&tic));
        tic.is_sparse = false;
        tic.max_mip_level = 1;
        assert!(tic_can_use_2d_rt_alias_view(&tic));
        tic.res_max_mip_level = 1;
        assert!(!tic_can_use_2d_rt_alias_view(&tic));
        tic.max_mip_level = 0;
        tic.res_max_mip_level = 0;
        tic.is_block_linear = false;
        tic.pitch_bytes = 1600 * 4;
        assert!(tic_can_use_2d_rt_alias_view(&tic));
        tic.texture_type = 4;
        assert!(!tic_can_use_2d_rt_alias_view(&tic));
        tic.texture_type = 1;
        tic.pitch_bytes = 0;
        assert!(!tic_can_use_2d_rt_alias_view(&tic));
        tic.pitch_bytes = 1600 * 4 - 32;
        assert!(!tic_can_use_2d_rt_alias_view(&tic));
        tic.is_block_linear = true;
        assert!(!tic_can_use_2d_rt_alias_view(&tic));
        tic.pitch_bytes = 0;
        assert!(tic_can_use_2d_rt_alias_view(&tic));
        tic.texture_type = 2;
        tic.depth = 4;
        assert!(tic_has_supported_rt_alias_layout(&tic));
        assert!(!tic_can_use_2d_rt_alias_view(&tic));
        tic.texture_type = 4;
        tic.depth = 1;
        assert!(tic_has_supported_rt_alias_layout(&tic));
        assert!(tic_can_use_2d_rt_alias_view(&tic));
        tic.texture_type = 1;
        tic.depth = 1;

        assert_eq!(
            rt_alias_sample_view_type(RtKey::new(1, 1600, 900, tic.gpu_va), Some(&tic), true,),
            vk::ImageViewType::TYPE_2D_ARRAY
        );
        assert_eq!(
            rt_alias_sample_view_type(RtKey::new(1, 1600, 900, tic.gpu_va), Some(&tic), false,),
            vk::ImageViewType::TYPE_2D
        );
    }

