    #[test]
    fn cube_array_upload_preserves_210_layers_across_eight_mips() {
        use crate::texture::{
            block_linear_mip_layout, swizzle_block_linear_strided, ComponentType, SwizzleSource,
            TicEntry, TicFormat,
        };

        let tic = TicEntry {
            format: TicFormat::R8,
            component_types: [ComponentType::Unorm; 4],
            swizzle: [
                SwizzleSource::R,
                SwizzleSource::R,
                SwizzleSource::R,
                SwizzleSource::One,
            ],
            gpu_va: 0x7fff_f000_0000,
            width: 32,
            height: 32,
            block_width_log2: 0,
            block_height_log2: 2,
            block_depth_log2: 0,
            tile_width_spacing: 0,
            pitch_bytes: 0,
            is_block_linear: true,
            texture_type: 8,
            depth: 35,
            base_layer: 0,
            normalized_coords: true,
            is_srgb: false,
            is_sparse: false,
            msaa_mode: 0,
            max_mip_level: 7,
            res_min_mip_level: 0,
            res_max_mip_level: 7,
        };
        crate::pitch_oracle::clear_pitch_range(tic.gpu_va, 0x10_0000);
        let layers = tic_layer_count(&tic);
        assert_eq!(layers, 210);
        let layout = block_linear_mip_layout(&tic).unwrap();
        assert_eq!(layout.levels.len(), 8);

        let mut guest = vec![0u8; layout.guest_size_bytes(layers)];
        for layer in 0..layers as usize {
            for level in &layout.levels {
                let marker = (layer as u8)
                    .wrapping_mul(17)
                    .wrapping_add((level.level as u8).wrapping_mul(29));
                let linear = vec![marker; level.linear_size];
                let swizzled = swizzle_block_linear_strided(
                    &linear,
                    level.storage_width,
                    level.storage_height,
                    tic.format.src_bpp(),
                    level.block_height_log2,
                    level.stride_alignment_log2,
                );
                assert!(swizzled.len() <= level.guest_size);
                let start = layer * layout.layer_stride + level.guest_offset;
                guest[start..start + swizzled.len()].copy_from_slice(&swizzled);
            }
        }

        crate::pitch_oracle::record_pitch_dst(tic.gpu_va, 0x10_0000);
        let upload = texture_upload_data_with_layout(
            &guest,
            &tic,
            layers,
            layout.layer_stride,
            true,
            false,
            vk::Format::R8_UNORM,
        );
        crate::pitch_oracle::clear_pitch_range(tic.gpu_va, 0x10_0000);
        let upload = upload.unwrap();
        assert_eq!(upload.copies.len(), 8);

        let mut expected_offset = 0usize;
        for (copy, level) in upload.copies.iter().zip(&layout.levels) {
            assert_eq!(copy.buffer_offset as usize, expected_offset);
            assert_eq!(copy.mip_level, level.level);
            assert_eq!((copy.width, copy.height), (level.width, level.height));
            for layer in 0..layers as usize {
                let marker = (layer as u8)
                    .wrapping_mul(17)
                    .wrapping_add((level.level as u8).wrapping_mul(29));
                let start = expected_offset + layer * level.linear_size;
                let end = start + level.linear_size;
                assert!(upload.bytes[start..end].iter().all(|byte| *byte == marker));
            }
            expected_offset += level.linear_size * layers as usize;
        }
        assert_eq!(upload.bytes.len(), expected_offset);
    }

    #[test]
    fn texture_view_layers_preserve_valid_subresources_and_reject_overflow() {
        assert_eq!(
            texture_view_layer_range(6, 0, 6, false, true, false, false).unwrap(),
            (0, 6)
        );
        assert!(texture_view_layer_range(6, 2, 6, false, true, false, false).is_err());
        assert_eq!(
            texture_view_layer_range(10, 4, 6, false, true, false, false).unwrap(),
            (4, 6)
        );
        assert!(texture_view_layer_range(7, 0, 7, false, false, true, false).is_err());
        assert_eq!(
            texture_view_layer_range(12, 0, 12, false, false, true, false).unwrap(),
            (0, 12)
        );
        assert!(texture_view_layer_range(6, 0, 2, false, false, false, false).is_err());
    }

    #[test]
    fn integer_textures_always_use_integer_safe_samplers() {
        use nexium_spirv::TextureNumericType;

        assert!(!texture_requires_integer_sampler(
            TextureNumericType::Float,
            false
        ));
        assert!(texture_requires_integer_sampler(
            TextureNumericType::Float,
            true
        ));
        assert!(texture_requires_integer_sampler(
            TextureNumericType::Uint,
            false
        ));
        assert!(texture_requires_integer_sampler(
            TextureNumericType::Sint,
            false
        ));
    }

    #[test]
    fn r16g16b16a16_format_selection_is_typed_and_fail_closed() {
        use crate::texture::{ComponentType, SwizzleSource, TicEntry, TicFormat};
        use nexium_spirv::TextureNumericType;

        let mut tic = TicEntry {
            format: TicFormat::R16G16B16A16,
            component_types: [ComponentType::Float; 4],
            swizzle: [SwizzleSource::R; 4],
            gpu_va: 1,
            width: 1,
            height: 1,
            block_width_log2: 0,
            block_height_log2: 0,
            block_depth_log2: 0,
            tile_width_spacing: 0,
            pitch_bytes: 0,
            is_block_linear: true,
            texture_type: 1,
            depth: 1,
            base_layer: 0,
            normalized_coords: true,
            is_srgb: false,
            is_sparse: false,
            msaa_mode: 0,
            max_mip_level: 0,
            res_min_mip_level: 0,
            res_max_mip_level: 0,
        };
        assert_eq!(
            texture_image_format_for_tic(&tic, TextureNumericType::Float).unwrap(),
            vk::Format::R16G16B16A16_SFLOAT
        );
        tic.component_types = [ComponentType::Unorm; 4];
        assert_eq!(
            texture_image_format_for_tic(&tic, TextureNumericType::Float).unwrap(),
            vk::Format::R16G16B16A16_UNORM
        );
        tic.component_types[3] = ComponentType::Float;
        assert!(texture_image_format_for_tic(&tic, TextureNumericType::Float).is_err());

        tic.format = TicFormat::R16;
        tic.component_types = [ComponentType::Float; 4];
        assert_eq!(
            texture_image_format_for_tic(&tic, TextureNumericType::Float).unwrap(),
            vk::Format::R16_SFLOAT
        );
        let half = [0x00, 0x3c, 0x00, 0x38];
        assert_eq!(
            texture_level_upload(
                &half,
                TicFormat::R16,
                2,
                1,
                1,
                ComponentType::Float,
                vk::Format::R16_SFLOAT,
            ),
            half
        );

        tic.format = TicFormat::B10G11R11;
        assert_eq!(
            texture_image_format_for_tic(&tic, TextureNumericType::Float).unwrap(),
            vk::Format::B10G11R11_UFLOAT_PACK32
        );
        let packed = 0x8abc_def0u32.to_le_bytes();
        assert_eq!(
            texture_level_upload(
                &packed,
                TicFormat::B10G11R11,
                1,
                1,
                1,
                ComponentType::Float,
                vk::Format::B10G11R11_UFLOAT_PACK32,
            ),
            packed
        );

        tic.component_types = [ComponentType::Unorm; 4];
        tic.is_srgb = true;
        tic.format = TicFormat::R8;
        assert_eq!(
            texture_image_format_for_tic(&tic, TextureNumericType::Float).unwrap(),
            vk::Format::R8_SRGB
        );
        assert_eq!(
            texture_level_upload(
                &[0x80],
                TicFormat::R8,
                1,
                1,
                1,
                ComponentType::Unorm,
                vk::Format::R8_SRGB,
            ),
            [0x80]
        );
        tic.format = TicFormat::R8G8;
        assert_eq!(
            texture_image_format_for_tic(&tic, TextureNumericType::Float).unwrap(),
            vk::Format::R8G8_SRGB
        );
        tic.format = TicFormat::R16;
        assert!(texture_image_format_for_tic(&tic, TextureNumericType::Float).is_err());

        tic.format = TicFormat::BC5;
        tic.component_types = [ComponentType::Snorm; 4];
        tic.is_srgb = false;
        assert_eq!(
            texture_image_format_for_tic(&tic, TextureNumericType::Float).unwrap(),
            vk::Format::BC5_SNORM_BLOCK
        );
        assert!(texture_image_format_for_tic(&tic, TextureNumericType::Uint).is_err());
        let block = [0xc0, 0x40, 0, 0, 0, 0, 0, 0, 0x20, 0xe0, 0, 0, 0, 0, 0, 0];
        let uploaded = texture_level_upload(
            &block,
            TicFormat::BC5,
            4,
            4,
            1,
            ComponentType::Snorm,
            vk::Format::BC5_SNORM_BLOCK,
        );
        assert_eq!(uploaded, block);

        tic.format = TicFormat::BC6U;
        tic.component_types = [ComponentType::Float; 4];
        assert_eq!(
            texture_image_format_for_tic(&tic, TextureNumericType::Float).unwrap(),
            vk::Format::BC6H_UFLOAT_BLOCK
        );
        assert_eq!(
            texture_level_upload(
                &block,
                TicFormat::BC6U,
                4,
                4,
                1,
                ComponentType::Float,
                vk::Format::BC6H_UFLOAT_BLOCK,
            ),
            block
        );
        assert!(texture_image_format_for_tic(&tic, TextureNumericType::Uint).is_err());

        tic.format = TicFormat::BC4;
        tic.component_types = [ComponentType::Snorm; 4];
        assert_eq!(
            texture_image_format_for_tic(&tic, TextureNumericType::Float).unwrap(),
            vk::Format::BC4_SNORM_BLOCK
        );
        assert_eq!(
            texture_level_upload(
                &block[..8],
                TicFormat::BC4,
                4,
                4,
                1,
                ComponentType::Snorm,
                vk::Format::BC4_SNORM_BLOCK,
            ),
            block[..8]
        );

        tic.format = TicFormat::BC5;
        tic.component_types[1] = ComponentType::Unorm;
        assert!(texture_image_format_for_tic(&tic, TextureNumericType::Float).is_err());
        tic.component_types = [ComponentType::Snorm; 4];
        tic.is_srgb = true;
        assert!(texture_image_format_for_tic(&tic, TextureNumericType::Float).is_err());
    }

    #[test]
    fn native_bc_selection_preserves_types_srgb_and_device_fallback() {
        use crate::texture::{ComponentType, TicFormat};
        use nexium_spirv::TextureNumericType::{Float, Uint};
        let mut tic = group_memo_test_tic(0x7fff_f100_0000);
        for (guest, linear, srgb) in [
            (
                TicFormat::BC1,
                vk::Format::BC1_RGBA_UNORM_BLOCK,
                vk::Format::BC1_RGBA_SRGB_BLOCK,
            ),
            (
                TicFormat::BC2,
                vk::Format::BC2_UNORM_BLOCK,
                vk::Format::BC2_SRGB_BLOCK,
            ),
            (
                TicFormat::BC3,
                vk::Format::BC3_UNORM_BLOCK,
                vk::Format::BC3_SRGB_BLOCK,
            ),
            (
                TicFormat::BC7,
                vk::Format::BC7_UNORM_BLOCK,
                vk::Format::BC7_SRGB_BLOCK,
            ),
        ] {
            tic.format = guest;
            tic.is_srgb = false;
            assert_eq!(
                super::native_bc_texture_format(&tic, Float, true),
                Some(linear)
            );
            assert_eq!(
                super::graphics_texture_image_format(&tic, Float, &[linear]).unwrap(),
                linear
            );
            assert_eq!(
                super::graphics_texture_image_format(&tic, Float, &[]).unwrap(),
                vk::Format::R8G8B8A8_UNORM
            );
            assert_eq!(
                super::graphics_texture_image_format(&tic, Float, &[srgb]).unwrap(),
                vk::Format::R8G8B8A8_UNORM
            );
            tic.is_srgb = true;
            assert_eq!(
                super::native_bc_texture_format(&tic, Float, true),
                Some(srgb)
            );
            assert_eq!(
                super::native_bc_texture_format(&tic, Float, false),
                Some(linear)
            );
            assert_eq!(super::native_bc_texture_format(&tic, Uint, true), None);
        }
        for (guest, host) in [
            (TicFormat::BC4, vk::Format::BC4_UNORM_BLOCK),
            (TicFormat::BC5, vk::Format::BC5_UNORM_BLOCK),
        ] {
            tic.format = guest;
            tic.is_srgb = false;
            assert_eq!(
                super::native_bc_texture_format(&tic, Float, true),
                Some(host)
            );
            tic.is_srgb = true;
            assert_eq!(super::native_bc_texture_format(&tic, Float, true), None);
        }
        tic.is_srgb = false;
        tic.component_types[1] = ComponentType::Snorm;
        assert_eq!(super::native_bc_texture_format(&tic, Float, true), None);
        assert!(
            super::graphics_texture_image_format(&tic, Float, super::NATIVE_BC_FORMATS).is_err()
        );
        tic.component_types = [ComponentType::Snorm; 4];
        assert_eq!(
            super::graphics_texture_image_format(&tic, Float, super::NATIVE_BC_FORMATS).unwrap(),
            vk::Format::BC5_SNORM_BLOCK
        );
        tic.component_types = [ComponentType::Unorm; 4];
        tic.texture_type = 2;
        assert_eq!(super::native_bc_texture_format(&tic, Float, true), None);
    }

    #[test]
    fn native_bc_upload_preserves_blocks_layers_and_partial_mips() {
        use crate::texture::{block_linear_mip_layout, swizzle_block_linear_strided, TicFormat};
        for (guest_format, host_format) in [
            (TicFormat::BC1, vk::Format::BC1_RGBA_SRGB_BLOCK),
            (TicFormat::BC2, vk::Format::BC2_UNORM_BLOCK),
            (TicFormat::BC3, vk::Format::BC3_SRGB_BLOCK),
            (TicFormat::BC4, vk::Format::BC4_UNORM_BLOCK),
            (TicFormat::BC5, vk::Format::BC5_UNORM_BLOCK),
            (TicFormat::BC7, vk::Format::BC7_SRGB_BLOCK),
        ] {
            let mut tic = group_memo_test_tic(0x7fff_f200_0000);
            tic.format = guest_format;
            tic.width = 37;
            tic.height = 19;
            tic.is_block_linear = true;
            tic.block_height_log2 = 2;
            tic.texture_type = 5;
            tic.depth = 3;
            tic.max_mip_level = 5;
            tic.res_max_mip_level = 5;
            let layers = 3;
            let layout = block_linear_mip_layout(&tic).unwrap();
            let mut guest = vec![0; layout.guest_size_bytes(layers)];
            let mut expected = Vec::new();
            let mut offsets = Vec::new();
            for level in &layout.levels {
                offsets.push(expected.len() as u64);
                for layer in 0..layers as usize {
                    let bytes: Vec<_> = (0..level.linear_size)
                        .map(|i| {
                            (i as u8)
                                .wrapping_mul(37)
                                .wrapping_add((layer * 17 + level.level as usize * 23) as u8)
                        })
                        .collect();
                    let swizzled = swizzle_block_linear_strided(
                        &bytes,
                        level.storage_width,
                        level.storage_height,
                        tic.format.src_bpp(),
                        level.block_height_log2,
                        level.stride_alignment_log2,
                    );
                    let start = layer * layout.layer_stride + level.guest_offset;
                    guest[start..start + swizzled.len()].copy_from_slice(&swizzled);
                    expected.extend(bytes);
                }
            }
            let upload = texture_upload_data_with_layout(
                &guest,
                &tic,
                layers,
                layout.layer_stride,
                true,
                false,
                host_format,
            )
            .unwrap();
            assert_eq!(upload.bytes, expected, "{guest_format:?}");
            assert_eq!(upload.copies.len(), 6);
            for ((copy, level), offset) in upload.copies.iter().zip(&layout.levels).zip(offsets) {
                assert_eq!(copy.buffer_offset, offset);
                assert_eq!(copy.buffer_offset % tic.format.src_bpp() as u64, 0);
                assert_eq!((copy.width, copy.height), (level.width, level.height));
                assert_eq!(copy.mip_level, level.level);
            }
            assert!(texture_upload_data_with_layout(
                &guest[..guest.len() - 1],
                &tic,
                layers,
                layout.layer_stride,
                true,
                false,
                host_format
            )
            .is_err());
        }
    }

    #[test]
    fn native_bc_cpu_fallback_preserves_transparent_bc1_and_two_channel_bc5() {
        use crate::texture::{ComponentType, TicFormat};
        let transparent = [0, 0, 0, 0, 255, 255, 255, 255];
        assert_eq!(
            texture_level_upload(
                &transparent,
                TicFormat::BC1,
                4,
                4,
                1,
                ComponentType::Unorm,
                vk::Format::BC1_RGBA_UNORM_BLOCK
            ),
            transparent
        );
        assert_eq!(
            texture_level_upload(
                &transparent,
                TicFormat::BC1,
                4,
                4,
                1,
                ComponentType::Unorm,
                vk::Format::R8G8B8A8_UNORM
            ),
            vec![0; 64]
        );
        let two_channels = [32, 32, 0, 0, 0, 0, 0, 0, 192, 192, 0, 0, 0, 0, 0, 0];
        let rgba = texture_level_upload(
            &two_channels,
            TicFormat::BC5,
            4,
            4,
            1,
            ComponentType::Unorm,
            vk::Format::R8G8B8A8_UNORM,
        );
        for pixel in rgba.chunks_exact(4) {
            assert_eq!(pixel, [32, 192, 0, 255]);
        }
    }

    #[test]
    fn g24r8_scalar_upload_preserves_stencil_and_depth() {
        let packed = 0x1234_56abu32.to_le_bytes();
        let uint = g24r8_scalar_upload(&packed, nexium_spirv::TextureNumericType::Uint);
        assert_eq!(u32::from_le_bytes(uint.try_into().unwrap()), 0xab);

        let float = g24r8_scalar_upload(&packed, nexium_spirv::TextureNumericType::Float);
        let depth = f32::from_le_bytes(float.try_into().unwrap());
        let expected = 0x12_3456 as f32 / 0x00ff_ffff as f32;
        assert!((depth - expected).abs() <= f32::EPSILON);
    }

    #[test]
    fn g24r8_scalar_view_maps_logical_green_to_red() {
        use crate::texture::{SwizzleSource, TicFormat};

        assert_eq!(
            texture_view_swizzle(
                TicFormat::G24R8,
                nexium_spirv::TextureNumericType::Float,
                [
                    SwizzleSource::G,
                    SwizzleSource::R,
                    SwizzleSource::One,
                    SwizzleSource::Zero,
                ],
            ),
            [
                SwizzleSource::R,
                SwizzleSource::R,
                SwizzleSource::One,
                SwizzleSource::Zero,
            ]
        );

        let stencil_swizzle = [
            SwizzleSource::G,
            SwizzleSource::R,
            SwizzleSource::One,
            SwizzleSource::Zero,
        ];
        assert_eq!(
            texture_view_swizzle(
                TicFormat::G24R8,
                nexium_spirv::TextureNumericType::Uint,
                stencil_swizzle,
            ),
            stencil_swizzle
        );
    }

    #[test]
    fn typed_texture_bindings_reject_numeric_mismatches() {
        use nexium_spirv::TextureNumericType;

        assert!(texture_numeric_type_matches_format(
            TextureNumericType::Uint,
            vk::Format::R32_UINT,
        ));
        assert!(!texture_numeric_type_matches_format(
            TextureNumericType::Uint,
            vk::Format::R8G8B8A8_UNORM,
        ));
        assert!(!texture_numeric_type_matches_format(
            TextureNumericType::Uint,
            vk::Format::D32_SFLOAT,
        ));
        assert!(texture_numeric_type_matches_format(
            TextureNumericType::Float,
            vk::Format::D32_SFLOAT,
        ));
    }

    #[test]
    fn g24r8_rt_alias_selects_only_the_stencil_aspect() {
        use crate::texture::{SwizzleSource, TicFormat};

        let all_r = [SwizzleSource::R; 4];
        let combined = vk::ImageAspectFlags::DEPTH | vk::ImageAspectFlags::STENCIL;
        assert_eq!(
            depth_stencil_sample_aspect(TicFormat::G24R8, all_r, combined),
            Some(vk::ImageAspectFlags::STENCIL),
        );
        let mapping = depth_stencil_component_mapping([
            SwizzleSource::G,
            SwizzleSource::R,
            SwizzleSource::One,
            SwizzleSource::Zero,
        ]);
        assert_eq!(mapping.r, vk::ComponentSwizzle::R);
        assert_eq!(mapping.g, vk::ComponentSwizzle::R);
        assert_eq!(mapping.b, vk::ComponentSwizzle::ONE);
        assert_eq!(mapping.a, vk::ComponentSwizzle::ZERO);
        assert_eq!(
            depth_stencil_sample_aspect(TicFormat::G24R8, all_r, vk::ImageAspectFlags::DEPTH,),
            None,
        );
    }

    #[test]
    fn integer_alias_border_colors_never_use_float_variants() {
        assert_eq!(
            vk_integer_border_color([0; 4]),
            vk::BorderColor::INT_TRANSPARENT_BLACK,
        );
        assert_eq!(
            vk_integer_border_color([1; 4]),
            vk::BorderColor::INT_OPAQUE_WHITE,
        );
        assert_eq!(
            vk_integer_border_color([2, 3, 4, 5]),
            vk::BorderColor::INT_OPAQUE_BLACK,
        );
    }
